/**
 * A typed request function for a module generated by openapi-shape.
 *
 * The generated `contract` says how each request goes over the wire
 * (parameter styles, media types, security, servers), and its type carries
 * the generated `Endpoints` and `Security`: `createClient({ contract })`. Requests
 * go to an adapter (by default, `fetch`). Response bodies are trusted, not
 * validated. This module has no imports so it can ship in any runtime.
 */

/**
 * The runtime details a generated module exports as `contract`. Encodings are
 * listed only where they differ from OpenAPI's defaults.
 */
export interface Contract<Endpoints = unknown, Security = Record<never, never>> {
  /** Carries the generated types for inference; never set. */
  readonly types?: { readonly endpoints: Endpoints; readonly security: Security }
  /** Server URLs with variables at their defaults; requests use the first unless `server` is given. */
  readonly servers: readonly string[]
  /** Security schemes by name. */
  readonly security?: Readonly<Record<string, SecurityScheme>>
  /** Default security requirements; any one of them suffices. */
  readonly requires?: readonly SecurityRequirement[]
  readonly endpoints: { readonly [K in keyof Endpoints]?: EndpointContract }
}

/** Security scheme names, each with its required scopes. */
type SecurityRequirement = Readonly<Record<string, readonly string[]>>

/** A security scheme: its `type`, and where its credential goes (`in` and `name`, or the HTTP `scheme`). */
interface SecurityScheme {
  readonly type: string
  readonly in?: string
  readonly name?: string
  readonly scheme?: string
}

/** How a value is serialized; absent fields take OpenAPI's defaults. */
interface Encoding {
  readonly style?: string
  readonly explode?: boolean
  readonly allowReserved?: boolean
  /** The media type of a parameter's `content`, or an Encoding Object's `contentType`. */
  readonly contentType?: string
}

interface EndpointContract {
  readonly servers?: readonly string[]
  readonly requires?: readonly SecurityRequirement[]
  readonly params?: Readonly<Record<string, Encoding>>
  readonly query?: Readonly<Record<string, Encoding>>
  /** Media type of the 3.2 `querystring` parameter. */
  readonly querystring?: string
  readonly headers?: Readonly<Record<string, Encoding>>
  readonly cookies?: Readonly<Record<string, Encoding>>
  /** The media type sent when the call names none and JSON is not accepted. */
  readonly contentType?: string
  /** Encoding Objects of form and multipart bodies, by media type and property. */
  readonly encoding?: Readonly<Record<string, Readonly<Record<string, Encoding>>>>
}

/** The shape of one entry of a generated `Endpoints` interface. */
interface Operation {
  params?: object
  query?: unknown
  headers?: object
  cookies?: object
  /** Media type → body type. */
  body?: object
  /** Status → response body type. */
  response: object
  responseHeaders?: object
}

/** What a client hands to its adapter. */
export interface AdapterRequest<Options = unknown> {
  method: string
  url: string
  /** Lowercase header names. */
  headers: Record<string, string>
  body: BodyLike | string | undefined
  options: Options | undefined
}

/** Performs a request and resolves to the decoded success body; rejects otherwise. */
export type Adapter<Options = unknown> = (request: AdapterRequest<Options>) => Promise<unknown>

export interface ClientOptions<Endpoints, Security, Options = FetchOptions> {
  /** The generated `contract`. */
  contract: Contract<Endpoints, Security>
  /** The server URL endpoint paths go under. Default: the endpoint's own server, else the document's first. */
  server?: string
  /** @deprecated Renamed to `server`; refused, so that requests never silently go elsewhere. */
  baseUrl?: never
  /** Credentials by security scheme; applied where an operation's security requires them. */
  security?: [keyof Security] extends [never] ? Record<string, never> : Credentials<Security>
  /** Sent with every request; per-call `headers` override them. */
  headers?: Record<string, string>
  /** Default adapter options; plain objects are shallow-merged with per-call `options`. */
  options?: NoInfer<Options>
  /** Transport. Default: {@link fetchAdapter} with the global `fetch`. */
  adapter?: Adapter<Options>
}

/** Each credential as a value, or a function returning one (called per request, e.g. to refresh a token). */
type Credentials<Security> = {
  [K in keyof Security]?: NonNullable<Security[K]> | (() => Credential<NonNullable<Security[K]>>)
}
/** What a credential function returns; nothing moves on to the operation's next security requirement. */
type Credential<T> = T | undefined | Promise<T | undefined>

export type Client<Endpoints, Options = FetchOptions> = <K extends keyof Endpoints & string>(
  endpoint: K,
  ...init: Empty extends RequestOptions<OperationOf<Endpoints, K>, Options>
    ? [init?: RequestOptions<OperationOf<Endpoints, K>, Options>]
    : [init: RequestOptions<OperationOf<Endpoints, K>, Options>]
) => Promise<SuccessOf<OperationOf<Endpoints, K>>>

/** Per-call input for one operation. */
type RequestOptions<Op extends Operation, Options = FetchOptions> = Field<"params", Op> &
  Field<"query", Op> &
  OpenField<"headers", Op> &
  OpenField<"cookies", Op> &
  BodyField<Op> & { options?: Options }

/** Response body for 2xx statuses; `default` when no 2xx is declared; otherwise `unknown`. */
export type SuccessOf<Op extends Operation> = [SuccessKey<Op>] extends [never]
  ? "default" extends keyof Op["response"]
    ? Op["response"]["default"]
    : unknown
  : Op["response"][SuccessKey<Op>]

/** Response body for 4xx/5xx statuses and `default`. */
export type ErrorOf<Op extends Operation> = Op["response"][Extract<
  keyof Op["response"],
  `4${string}` | `5${string}` | "default"
>]

/** Request options accepted by {@link fetchAdapter}. */
export type FetchOptions = Omit<FetchInit, "method" | "headers" | "body">

/** A non-2xx response from {@link fetchAdapter}; `body` is decoded like a success body. */
export class HttpError extends Error {
  readonly status: number
  readonly body: unknown
  readonly response: FetchResponse

  constructor(response: FetchResponse, body: unknown) {
    super(`HTTP ${response.status}${response.statusText ? ` ${response.statusText}` : ""}`)
    this.name = "HttpError"
    this.status = response.status
    this.body = body
    this.response = response
  }
}

/**
 * An adapter over `fetch`. JSON content types are parsed; JSON sequences
 * (`application/jsonl`, `application/x-ndjson`, `application/json-seq`) and
 * `text/event-stream` become arrays of items; `text/*` is read as text; empty
 * responses resolve to `undefined`; anything else to a Blob. Non-2xx
 * responses reject with {@link HttpError}.
 */
export function fetchAdapter(fetchImpl: FetchFunction = globalThis.fetch): Adapter<FetchOptions> {
  return async ({ method, url, headers, body, options }) => {
    const init: Record<string, unknown> = { ...options, method, headers, body }
    // Streaming request bodies need half duplex (Fetch Standard).
    if (isStream(body)) init.duplex = "half"
    const response = await (fetchImpl as typeof fetch)(url, init as RequestInit)
    if (response.ok) return readBody(response, method)
    // An error body that does not decode is still the error's body.
    const raw = response.clone()
    const data = await readBody(response, method).catch(() => raw.text())
    throw new HttpError(response as FetchResponse, data)
  }
}

/** Create a typed request function from a generated module's `contract`. */
export function createClient<Endpoints, Security, Options = FetchOptions>(
  config: ClientOptions<Endpoints, Security, Options>,
): Client<Endpoints, Options> {
  // Ignored, it would send requests to the document's server, often production.
  if ("baseUrl" in config) throw new TypeError("The baseUrl option is now called server")
  const contract = config.contract as Contract
  const endpoints = contract.endpoints as Readonly<Record<string, EndpointContract | undefined>>
  const credentials = config.security as Record<string, unknown> | undefined
  const adapter = (config.adapter ?? fetchAdapter()) as Adapter<unknown>

  const request = async (endpoint: string, init: RuntimeOptions = {}): Promise<unknown> => {
    const space = endpoint.indexOf(" ")
    if (space <= 0) throw new Error(`Invalid endpoint "${endpoint}"; expected "METHOD /path"`)
    const method = endpoint.slice(0, space)
    const declared = endpoints[endpoint]
    const headers = lowercase(config.headers)
    const cookies: Pair[] = []

    const applied = await authenticate(contract, declared, credentials)
    Object.assign(headers, applied.headers)
    cookies.push(...applied.cookies)

    let url = expandPath(endpoint.slice(space + 1), init.params, declared?.params)
    const search = [
      init.query === undefined ? "" : serializeQuery(init.query, declared),
      ...applied.query.map(([k, v]) => `${encode(k, null)}=${encode(v, null)}`),
    ]
    url = appendQuery(url, search.filter(Boolean).join("&"))
    if (!/^https?:\/\//i.test(url)) {
      const base = config.server ?? declared?.servers?.[0] ?? contract.servers[0] ?? ""
      url = base.replace(/\/+$/, "") + url
    }

    let body: BodyLike | string | undefined
    if (init.body !== undefined) {
      const contentType = init.contentType ?? declared?.contentType
      const encoded = encodeBody(init.body, contentType, declared)
      body = encoded.body
      // Without a label, the body's own type (a Blob's, FormData's boundary) applies.
      if (encoded.contentType === undefined) delete headers["content-type"]
      else headers["content-type"] = encoded.contentType
    }
    for (const [name, value] of Object.entries(init.headers ?? {})) {
      if (value == null) continue
      const encoding = normalize(byLowercase(declared?.headers, name), "simple")
      headers[name.toLowerCase()] = encoding.contentType
        ? encodeContent(value, encoding.contentType)
        : delimited(value, encoding.explode, ",", (s) => s)
    }
    for (const [name, value] of Object.entries(init.cookies ?? {})) {
      cookies.push(...cookiePairs(name, value, normalize(declared?.cookies?.[name], "form")))
    }
    if (cookies.length > 0) {
      const own = cookies.map(([k, v]) => `${k}=${v}`).join("; ")
      headers.cookie = [headers.cookie, own].filter(Boolean).join("; ")
    }

    return await adapter({
      method,
      url,
      headers,
      body,
      options: mergeOptions(config.options, init.options),
    })
  }
  return request as unknown as Client<Endpoints, Options>
}

// --- serialization --------------------------------------------------------------

interface RuntimeOptions {
  params?: Record<string, unknown>
  query?: unknown
  headers?: Record<string, unknown>
  cookies?: Record<string, unknown>
  body?: unknown
  contentType?: string
  options?: unknown
}

type Pair = [name: string, value: string]

interface Normalized {
  style: string
  explode: boolean
  allowReserved: boolean
  contentType: string | undefined
}

// `deepObject` is defined for explode: true only.
const EXPLODED = new Set(["form", "cookie", "deepObject"])
/** Record separator, which starts each item of `application/json-seq`. */
const RS = String.fromCharCode(0x1e)

function normalize(spec: Encoding | undefined, defaultStyle: string): Normalized {
  const style = spec?.style ?? defaultStyle
  return {
    style,
    explode: spec?.explode ?? EXPLODED.has(style),
    allowReserved: spec?.allowReserved ?? false,
    contentType: spec?.contentType,
  }
}

/** Path template expansion; `simple` style unless declared otherwise. */
function expandPath(
  path: string,
  params: Record<string, unknown> | undefined,
  declared: EndpointContract["params"],
): string {
  return path
    .split("/")
    .map((segment) => {
      const expanded = segment.replaceAll(/\{([^{}]+)\}/g, (_, name: string) =>
        expandParam(name, params?.[name], declared?.[name]),
      )
      // A value that leaves a segment empty, ".", or ".." would send the request
      // to another resource once the URL is normalized.
      const parts = expanded.split("/")
      const moves = parts.some((part) => /^\.{0,2}$/.test(part.replaceAll(/%2e/gi, ".")))
      if (expanded !== segment && moves) {
        throw new Error(`Path parameters turn "${segment}" into "${expanded}", another resource`)
      }
      return expanded
    })
    .join("/")
}

/** A path template variable; `simple` style unless declared otherwise. */
function expandParam(name: string, value: unknown, spec: Encoding | undefined): string {
  if (value == null) throw new Error(`Missing path parameter "${name}"`)
  const { style, explode, allowReserved, contentType } = normalize(spec, "simple")
  const enc = (s: string): string => encode(s, allowReserved ? PATH_RESERVED : null)
  if (contentType) return enc(encodeContent(value, contentType))
  if (style === "label") return `.${delimited(value, explode, explode ? "." : ",", enc)}`
  if (style === "matrix") {
    if (Array.isArray(value) && explode) {
      return value.map((v) => `;${name}=${enc(scalar(v))}`).join("")
    }
    if (isPlainObject(value) && explode) {
      return Object.entries(value)
        .map(([k, v]) => `;${enc(k)}=${enc(scalar(v))}`)
        .join("")
    }
    return `;${name}=${delimited(value, false, ",", enc)}`
  }
  return delimited(value, explode, ",", enc)
}

/** Arrays and objects as delimited lists; exploded objects as `key=value` items. */
function delimited(
  value: unknown,
  explode: boolean,
  separator: string,
  enc: (s: string) => string,
): string {
  if (Array.isArray(value)) return value.map((v) => enc(scalar(v))).join(separator)
  if (isPlainObject(value)) {
    const entries = Object.entries(value).filter(([, v]) => v != null)
    return explode
      ? entries.map(([k, v]) => `${enc(k)}=${enc(scalar(v))}`).join(separator)
      : entries.flatMap(([k, v]) => [enc(k), enc(scalar(v))]).join(",")
  }
  return enc(scalar(value))
}

function serializeQuery(query: unknown, declared: EndpointContract | undefined): string {
  if (declared?.querystring !== undefined) {
    return encode(encodeContent(query, declared.querystring), null)
  }
  if (!isPlainObject(query)) return encode(scalar(query), null)
  return formFields(query, declared?.query ?? {})
}

/** Fields as `name=value&…`, each serialized as its encoding says (OpenAPI default: form, exploded). */
function formFields(
  fields: Record<string, unknown>,
  encodings: Readonly<Record<string, Encoding>>,
): string {
  return Object.entries(fields)
    .flatMap(([name, value]) => {
      const encoding = normalize(encodings[name], "form")
      return formPairs(name, value, encoding).map(([k, v]) => `${encodeKey(k)}=${v}`)
    })
    .join("&")
}

/** `name=value` pairs for a query parameter or form field, by style (OpenAPI default: form, exploded). */
/** `[name, value]` pairs for a query parameter or form field, by style, percent-encoded. */
function formPairs(name: string, value: unknown, encoding: Normalized): Pair[] {
  if (value == null) return []
  const { style, explode, contentType } = encoding
  const enc = (s: string): string => encode(s, encoding.allowReserved ? QUERY_RESERVED : null)
  if (contentType) return [[name, enc(encodeContent(value, contentType))]]
  if (style === "deepObject") return brackets(name, value).map(([k, v]) => [k, enc(v)])
  // Commas stay as they are; a space or pipe must be percent-encoded.
  const separator = style === "spaceDelimited" ? "%20" : style === "pipeDelimited" ? "%7C" : ","
  if (Array.isArray(value)) {
    const items = value.filter((v) => v != null).map((v) => enc(scalar(v)))
    if (explode) return items.map((item) => [name, item])
    return [[name, items.join(separator)]]
  }
  if (isPlainObject(value)) {
    const entries = Object.entries(value).filter(([, v]) => v != null)
    // An exploded object contributes its properties as parameters.
    if (explode) return entries.map(([k, v]) => [k, enc(scalar(v))])
    return [[name, entries.flatMap(([k, v]) => [enc(k), enc(scalar(v))]).join(separator)]]
  }
  return [[name, enc(scalar(value))]]
}

/** `deepObject`: `name[key]=value`, nested objects and arrays indexed the same way. */
function brackets(name: string, value: unknown): Pair[] {
  if (value == null) return []
  if (Array.isArray(value)) return value.flatMap((v, i) => brackets(`${name}[${i}]`, v))
  if (isPlainObject(value)) {
    return Object.entries(value).flatMap(([k, v]) => brackets(`${name}[${k}]`, v))
  }
  return [[name, scalar(value)]]
}

function cookiePairs(name: string, value: unknown, encoding: Normalized): Pair[] {
  if (value == null) return []
  // `style: cookie` (3.2) does not percent-encode.
  const enc = encoding.style === "cookie" ? (s: string): string => s : encodeURIComponent
  if (encoding.contentType) return [[name, enc(encodeContent(value, encoding.contentType))]]
  if (Array.isArray(value) && encoding.explode) return value.map((v) => [name, enc(scalar(v))])
  if (isPlainObject(value) && encoding.explode) {
    return Object.entries(value).map(([k, v]) => [k, enc(scalar(v))])
  }
  return [[name, delimited(value, false, ",", enc)]]
}

/** A value serialized as a media type (parameters with `content`). */
function encodeContent(value: unknown, contentType: string): string {
  return mediaClass(contentType) === "json" ? toJson(value) : scalar(value)
}

/**
 * Reserved characters that `allowReserved` leaves as they are (RFC 3986): in a
 * path, all but those ending it (`?`, `#`) or not allowed there (`[`, `]`); in
 * a query or form field, also not `&`, `=`, and `+`, which delimit or mean a space
 * there (OpenAPI 3.1.1, "Parameter Object").
 */
const PATH_RESERVED = /%(?:3A|2F|40|21|24|26|27|28|29|2A|2B|2C|3B|3D)/gi
const QUERY_RESERVED = /%(?:3A|2F|3F|40|21|24|27|28|29|2A|2C|3B)/gi

/** Percent-encode; with `reserved`, those characters and existing percent-encodings are kept. */
function encode(value: string, reserved: RegExp | null): string {
  const encoded = encodeURIComponent(value)
  if (reserved === null) return encoded
  return encoded
    .replaceAll(reserved, (m) => decodeURIComponent(m))
    .replaceAll(/%25([0-9A-Fa-f]{2})/g, "%$1")
}

/** Bracket notation stays readable: `created[gte]`. */
function encodeKey(key: string): string {
  return encodeURIComponent(key).replaceAll("%5B", "[").replaceAll("%5D", "]")
}

function appendQuery(url: string, query: string): string {
  if (query === "") return url
  const hash = url.indexOf("#")
  const base = hash === -1 ? url : url.slice(0, hash)
  const fragment = hash === -1 ? "" : url.slice(hash)
  const separator = !base.includes("?") ? "?" : base.endsWith("?") || base.endsWith("&") ? "" : "&"
  return `${base}${separator}${query}${fragment}`
}

function encodeBody(
  body: unknown,
  contentType: string | undefined,
  declared: EndpointContract | undefined,
): { body: BodyLike | string; contentType: string | undefined } {
  const type = contentType ?? "application/json"
  const label = concrete(contentType)
  if (isBodyLike(body)) {
    // fetch derives multipart boundaries and form encodings itself.
    const own = isInstance(body, "FormData") || isInstance(body, "URLSearchParams")
    return { body, contentType: own ? undefined : label }
  }
  const fields = declared?.encoding?.[type] ?? {}
  switch (mediaClass(type)) {
    case "json":
      return { body: toJson(body), contentType: label ?? "application/json" }
    case "sequence": {
      if (!Array.isArray(body)) throw new TypeError(`A ${type} body must be an array of items`)
      const prefix = mediaTypeEssence(type).endsWith("json-seq") ? RS : ""
      const lines = body.map((item) => `${prefix}${toJson(item)}\n`)
      return { body: lines.join(""), contentType: label }
    }
    case "form": {
      // A string is already encoded.
      if (typeof body === "string") return { body, contentType: label }
      if (!isPlainObject(body)) throw new TypeError("A form body must be an object")
      return { body: formFields(body, fields), contentType: label }
    }
    case "multipart":
      return formData(body, fields)
    case "text":
      if (typeof body !== "string") throw new TypeError(`A ${type} body must be a string`)
      return { body, contentType: label ?? "text/plain" }
    case "events":
    case "binary":
      if (typeof body === "string") return { body, contentType: label }
      throw new TypeError(
        `Cannot encode a ${typeof body} as ${type}; pass it encoded, as a string or Blob`,
      )
  }
}

/**
 * A multipart/form-data body (RFC 7578), written out: `FormData` can give a
 * part a content type only by making it a file, which servers then treat as
 * an upload. Values go as given (line breaks are not converted).
 */
function formData(
  body: unknown,
  fields: Readonly<Record<string, Encoding>>,
): { body: BodyLike; contentType: string } {
  if (!isPlainObject(body)) throw new TypeError("A multipart/form-data body must be an object")
  const boundary = `openapi-shape-${Math.random().toString(36).slice(2)}${Math.random().toString(36).slice(2)}`
  const parts: BlobPart[] = []
  const append = (name: string, value: unknown): void => {
    if (value == null) return
    const declared = normalize(fields[name], "form").contentType
    // A part's declared media type labels it, when it names one.
    const label = declared === undefined || /[*,\r\n]/.test(declared) ? undefined : declared
    let disposition = `form-data; name="${quoted(name)}"`
    let type: string | undefined
    let content: BlobPart
    if (isInstance(value, "Blob")) {
      const file = (value as { name?: unknown }).name
      disposition += `; filename="${quoted(typeof file === "string" && file !== "" ? file : "blob")}"`
      type = label ?? ((value as Blob).type || "application/octet-stream")
      content = value as Blob
    } else {
      const json = isPlainObject(value) || Array.isArray(value)
      content = json ? toJson(value) : scalar(value)
      // Objects are JSON parts, as OpenAPI defaults; text is a plain field.
      // A declared type labels the part, in the UTF-8 it is sent in.
      const media = label ?? (json ? "application/json" : undefined)
      if (media !== undefined && !/^text\/plain\b/i.test(media)) {
        type = media.replace(/;\s*charset=[^;]*/i, "; charset=utf-8")
      }
    }
    const headers = `Content-Disposition: ${disposition}\r\n${type === undefined ? "" : `Content-Type: ${type}\r\n`}`
    parts.push(`--${boundary}\r\n${headers}\r\n`, content, "\r\n")
  }
  for (const [name, value] of Object.entries(body)) {
    // Array properties become repeated parts with the same name.
    if (Array.isArray(value)) for (const item of value) append(name, item)
    else append(name, value)
  }
  parts.push(`--${boundary}--\r\n`)
  return {
    body: new Blob(parts) as unknown as BodyLike,
    contentType: `multipart/form-data; boundary=${boundary}`,
  }
}

/** A field name or filename in a quoted header parameter, escaped as the HTML Standard does. */
function quoted(value: string): string {
  return value.replaceAll("\n", "%0A").replaceAll("\r", "%0D").replaceAll('"', "%22")
}

// --- security -------------------------------------------------------------------

async function authenticate(
  contract: Contract,
  declared: EndpointContract | undefined,
  credentials: Record<string, unknown> | undefined,
): Promise<{ headers: Record<string, string>; query: Pair[]; cookies: Pair[] }> {
  const out = { headers: {} as Record<string, string>, query: [] as Pair[], cookies: [] as Pair[] }
  if (!credentials) return out
  const schemes = contract.security ?? {}
  // Mutual TLS is the transport's; every other scheme needs a credential.
  const needs = (name: string): boolean => schemes[name]?.type !== "mutualTLS"
  const requirements = declared?.requires ?? contract.requires
  // With no security declared, the credentials given are sent as they are.
  const candidates =
    requirements === undefined
      ? [
          Object.fromEntries(
            Object.keys(credentials)
              .filter((name) => credentials[name] !== undefined)
              .map((name) => [name, []]),
          ),
        ]
      : // Requirements that use credentials come first, so that given ones are sent.
        [
          ...requirements.filter((r) => Object.keys(r).some((name) => needs(name))),
          ...requirements.filter((r) => !Object.keys(r).some((name) => needs(name))),
        ]
  // Each credential is resolved at most once per request, and only when a requirement uses it.
  const resolved = new Map<string, unknown>()
  const resolve = async (name: string): Promise<unknown> => {
    if (!resolved.has(name)) {
      const given = credentials[name]
      resolved.set(name, typeof given === "function" ? await (given as () => unknown)() : given)
    }
    return resolved.get(name)
  }
  for (const requirement of candidates) {
    const names = Object.keys(requirement).filter((name) => needs(name))
    if (!names.every((name) => credentials[name] !== undefined)) continue
    const values: unknown[] = []
    for (const name of names) {
      // oxlint-disable-next-line no-await-in-loop -- credentials resolve one at a time, on demand
      values.push(await resolve(name))
    }
    // A credential function that returns nothing leaves the requirement unmet.
    if (requirements !== undefined && values.some((value) => value == null)) continue
    names.forEach((name, i) => {
      const scheme = schemes[name]
      if (scheme !== undefined && values[i] != null) place(scheme, values[i], out)
    })
    return out
  }
  return out
}

/** Put a credential where its scheme says. */
function place(
  scheme: SecurityScheme,
  value: unknown,
  out: { headers: Record<string, string>; query: Pair[]; cookies: Pair[] },
): void {
  if (scheme.type === "apiKey") {
    const name = scheme.name ?? ""
    if (scheme.in === "header") out.headers[name.toLowerCase()] = String(value)
    else if (scheme.in === "query") out.query.push([name, String(value)])
    else out.cookies.push([name, encodeURIComponent(String(value))])
  } else if (scheme.type === "http" && scheme.scheme === "basic") {
    const { username, password } = value as { username: string; password: string }
    out.headers.authorization = `Basic ${base64(`${username}:${password}`)}`
  } else if (scheme.type === "http" && scheme.scheme !== "bearer") {
    const label = scheme.scheme ?? ""
    out.headers.authorization = `${label.charAt(0).toUpperCase()}${label.slice(1)} ${String(value)}`
  } else {
    out.headers.authorization = `Bearer ${String(value)}`
  }
}

function base64(text: string): string {
  let binary = ""
  for (const byte of new TextEncoder().encode(text)) binary += String.fromCharCode(byte)
  return btoa(binary)
}

// --- helpers --------------------------------------------------------------------

function mediaTypeEssence(mediaType: string): string {
  return mediaType.split(";", 1)[0].trim().toLowerCase()
}

type MediaClass = "json" | "events" | "sequence" | "text" | "form" | "multipart" | "binary"

/** How content of a media type is encoded and decoded; the generator types content by the same classes. */
function mediaClass(mediaType: string): MediaClass {
  const essence = mediaTypeEssence(mediaType)
  const [type = "", subtype = ""] = essence.split("/", 2)
  if (essence === "*/*" || essence === "application/*") return "json"
  if (subtype === "json" || subtype.endsWith("+json")) return "json"
  if (essence === "text/event-stream") return "events"
  if (
    essence === "application/jsonl" ||
    essence === "application/x-ndjson" ||
    essence === "application/json-seq" ||
    subtype.endsWith("+json-seq")
  ) {
    return "sequence"
  }
  if (type === "text") return "text"
  if (essence === "application/x-www-form-urlencoded") return "form"
  if (essence === "multipart/form-data") return "multipart"
  return "binary"
}

/** A wildcard media type cannot label a request. */
function concrete(contentType: string | undefined): string | undefined {
  return contentType === undefined || contentType.includes("*") ? undefined : contentType
}

/** A value as text: parameters, headers, cookies, form fields, and text parts. */
function scalar(value: unknown): string {
  if (value instanceof Date) return value.toISOString()
  // Raw bytes are typed Blob wherever a schema declares them; as text they cannot go.
  if (isInstance(value, "Blob")) throw new TypeError("A Blob cannot be sent as text")
  return typeof value === "object" && value !== null ? toJson(value) : String(value)
}

/** JSON text. A Blob has no JSON form, so it is refused rather than sent as `{}`. */
function toJson(value: unknown): string {
  const json = JSON.stringify(value, (_, item: unknown) => {
    if (isInstance(item, "Blob")) throw new TypeError("A Blob cannot be sent inside JSON")
    return item
  })
  if (json === undefined) throw new TypeError("The value is not JSON-serializable")
  return json
}

/** A header's entry, whatever the case of its name. */
function byLowercase<T>(map: Readonly<Record<string, T>> | undefined, name: string): T | undefined {
  const key = Object.keys(map ?? {}).find((k) => k.toLowerCase() === name.toLowerCase())
  return key === undefined ? undefined : map?.[key]
}

function lowercase(headers: Record<string, string> | undefined): Record<string, string> {
  const out: Record<string, string> = {}
  for (const [name, value] of Object.entries(headers ?? {})) out[name.toLowerCase()] = value
  return out
}

function mergeOptions(defaults: unknown, call: unknown): unknown {
  if (defaults === undefined) return call
  if (call === undefined) return defaults
  return isPlainObject(defaults) && isPlainObject(call) ? { ...defaults, ...call } : call
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false
  const proto: unknown = Object.getPrototypeOf(value)
  return proto === Object.prototype || proto === null
}

function isInstance(
  value: unknown,
  name: "Blob" | "FormData" | "URLSearchParams" | "ReadableStream",
): boolean {
  const ctor = (globalThis as Record<string, unknown>)[name]
  return typeof ctor === "function" && value instanceof ctor
}

function isBodyLike(value: unknown): value is BodyLike {
  return (
    isInstance(value, "Blob") ||
    isInstance(value, "FormData") ||
    isInstance(value, "URLSearchParams") ||
    value instanceof ArrayBuffer ||
    ArrayBuffer.isView(value) ||
    isStream(value)
  )
}

/** A web `ReadableStream`, or an async iterable such as a Node.js stream. */
function isStream(value: unknown): boolean {
  return (
    isInstance(value, "ReadableStream") ||
    (typeof value === "object" && value !== null && Symbol.asyncIterator in value)
  )
}

async function readBody(response: Response, method: string): Promise<unknown> {
  if (
    method === "HEAD" ||
    response.status === 204 ||
    response.status === 205 ||
    response.status === 304
  ) {
    return undefined
  }
  const type = response.headers.get("content-type") ?? ""
  switch (type === "" ? "binary" : mediaClass(type)) {
    case "json": {
      const text = await response.text()
      return text === "" ? undefined : JSON.parse(text)
    }
    case "sequence": {
      const separator = mediaTypeEssence(type).endsWith("json-seq") ? RS : "\n"
      const text = await response.text()
      return text
        .split(separator)
        .map((item) => item.trim())
        .filter((item) => item !== "")
        .map((item) => JSON.parse(item) as unknown)
    }
    case "events":
      return events(await response.text())
    case "text":
      return response.text()
    default: {
      // An empty body without a content type is no content.
      const blob = await response.blob()
      return blob.size === 0 && type === "" ? undefined : blob
    }
  }
}

interface ServerSentEvent {
  data: string
  event?: string
  id?: string
  retry?: number
}

/** Server-sent events, per the HTML standard's parsing rules. */
function events(text: string): ServerSentEvent[] {
  const out: ServerSentEvent[] = []
  for (const block of text.replaceAll(/\r\n?/g, "\n").split("\n\n")) {
    const data: string[] = []
    const event: ServerSentEvent = { data: "" }
    for (const line of block.split("\n")) {
      if (line === "" || line.startsWith(":")) continue
      const colon = line.indexOf(":")
      const field = colon === -1 ? line : line.slice(0, colon)
      const value = colon === -1 ? "" : line.slice(colon + 1).replace(/^ /, "")
      if (field === "data") data.push(value)
      else if (field === "event") event.event = value
      else if (field === "id") event.id = value
      else if (field === "retry" && /^\d+$/.test(value)) event.retry = Number(value)
    }
    // An event without data is not dispatched.
    if (data.length === 0) continue
    event.data = data.join("\n")
    out.push(event)
  }
  return out
}

// --- types ----------------------------------------------------------------------

// Derived from the global `fetch` when the environment declares one (DOM or Node types).
type FetchFunction = typeof globalThis extends { fetch: infer F }
  ? F
  : (url: string, init?: object) => Promise<FetchResponse>
type FetchInit = typeof globalThis extends {
  fetch: (input: never, init?: infer I) => unknown
}
  ? NonNullable<I>
  : { body?: unknown }
type FetchResponse = typeof globalThis extends {
  fetch: (...args: never[]) => Promise<infer R>
}
  ? R
  : { status: number; statusText: string; ok: boolean }

/** Values `fetch` accepts as a request body, other than strings. */
type BodyLike = Exclude<NonNullable<FetchInit["body"]>, string>

/** The empty object type: `Empty extends T` holds when every property of `T` is optional. */
type Empty = Record<never, never>

type OperationOf<Endpoints, K extends keyof Endpoints> = Endpoints[K] extends Operation
  ? Endpoints[K]
  : never
type SuccessKey<Op extends Operation> = Extract<keyof Op["response"], `2${string}`>

/** `{ params: P }` when declared and required, `{ params?: P }` when optional, else forbidden. */
type Field<Name extends "params" | "query", Op extends Operation> = Name extends keyof Op
  ? Empty extends Pick<Op, Name>
    ? Partial<Record<Name, Op[Name]>>
    : Empty extends Op[Name]
      ? Partial<Record<Name, Op[Name]>>
      : Record<Name, Op[Name]>
  : Partial<Record<Name, never>>

/** Declared headers/cookies keep their types; others are allowed. Never required per call. */
type OpenField<Name extends "headers" | "cookies", Op extends Operation> = Partial<
  Record<Name, (Name extends keyof Op ? Partial<Op[Name]> : Empty) & Record<string, unknown>>
>

type BodyField<Op extends Operation> = "body" extends keyof Op
  ? Empty extends Pick<Op, "body">
    ?
        | BodyVariant<NonNullable<Op["body"]>, DefaultMediaType<NonNullable<Op["body"]>>>
        | { body?: undefined; contentType?: undefined }
    : BodyVariant<NonNullable<Op["body"]>, DefaultMediaType<NonNullable<Op["body"]>>>
  : { body?: never; contentType?: never }

/** The media type sent when the call names none: one that takes JSON, else the only one declared. */
type DefaultMediaType<Content> = [JsonMediaType<keyof Content & string>] extends [never]
  ? Only<keyof Content & string>
  : JsonMediaType<keyof Content & string>
type JsonMediaType<M extends string> = M extends unknown
  ? Essence<M> extends "application/json" | "*/*" | "application/*"
    ? M
    : never
  : never
/** `M` when it is a single type, else `never`. */
type Only<M, All = M> = M extends unknown ? ([All] extends [M] ? M : never) : never

/** One variant per declared media type; `contentType` may be omitted for the default. */
type BodyVariant<Content, Default> = {
  [M in keyof Content & string]: [M] extends [Default]
    ? { contentType?: M; body: BodyValue<Content, M> }
    : { contentType: M; body: BodyValue<Content, M> }
}[keyof Content & string]

/** What the client can encode for a media type; others take ready-made bodies. */
type BodyValue<Content, M extends keyof Content & string> =
  IsEncodable<M> extends true ? Content[M] | BodyLike : BodyLike | string

type Essence<M extends string> = Lowercase<M extends `${infer E};${string}` ? Trim<E> : Trim<M>>
type Trim<S extends string> = S extends ` ${infer T}`
  ? Trim<T>
  : S extends `${infer T} `
    ? Trim<T>
    : S
/** Media types the client encodes (the `json`, `sequence`, `text`, `form`, and `multipart` classes). */
type IsEncodable<M extends string> =
  Essence<M> extends
    | "*/*"
    | "application/*"
    | `${string}/json`
    | `${string}+json`
    | "application/jsonl"
    | "application/x-ndjson"
    | "application/json-seq"
    | `${string}+json-seq`
    | "application/x-www-form-urlencoded"
    | "multipart/form-data"
    ? true
    : Essence<M> extends `text/${infer Subtype}`
      ? Subtype extends "event-stream"
        ? false
        : true
      : false
